let seed=83;function rng(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}const range=(a,b)=>a+rng()*(b-a),clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
