 let start=goal;if(!layer.walk[start]){let best=Infinity;for(let i=0;i<layer.walk.length;i++)if(layer.walk[i]){const d=(i%N-HALF+.5-p.x)**2+(Math.floor(i/N)-HALF+.5-p.z)**2;if(d<best){best=d;start=i}}}
