function isEpic(e){return e.type===3||e.type>=8}
function dropXP(x,z,value){const nearby=gems.find(g=>!g.heal&&Math.abs(g.x-x)<.8&&Math.abs(g.z-z)<.8&&!segmentWall(g.x,g.z,x,z));if(nearby)nearby.value+=value;else gems.push({x,z,value})}
function compactGems(){if(gems.length<120)return;const buckets=new Map(),kept=[];const cell=gems.length>750?6:3;for(const g of gems){if(g.heal){kept.push(g);continue}const key=Math.floor(g.x/cell)+','+Math.floor(g.z/cell),same=buckets.get(key)||[];const target=same.find(t=>!segmentWall(t.x,t.z,g.x,g.z));if(target)target.value+=g.value;else{same.push(g);buckets.set(key,same);kept.push(g)}}gems=kept}
