function drawKit(b){for(const f of combatFX){if(f.type==='chain'){const a=Math.atan2(f.x2-f.x,f.z2-f.z),mesh=geo('chain-beam',m=>m.box(0,0,.5,.018,.018,1,[.5,.8,1],1));b.add(mesh,f.x,.9,f.z,a,Math.hypot(f.x2-f.x,f.z2-f.z))}else if(f.type==='cleave'){for(let i=0;i<12;i++){const a=f.angle-.95+i*1.9/11;b.add(geo('cleave-spark',m=>m.sphere(0,0,0,.14,.1,.14,[1,.7,.22],1)),f.x+Math.sin(a)*f.r,.75,f.z+Math.cos(a)*f.r)}}else{b.ring(f.x,.12,f.z,Math.max(.15,f.r*(1-f.life/.45)),.09,f.color);b.ring(f.x,.15,f.z,f.r,.035,f.color)}}if(shieldTime>0){b.ring(p.x,.12,p.z,.85,.1,[.45,.7,1]);b.ring(p.x,1.1,p.z,.8,.035,[.65,.85,1])}}

