function restore(input){const s=P.validateSave(input);selected=s.hero;difficulty=s.difficulty;rewardTokens=(s.kit?.rewardTokens||[]).map(t=>({...t}));epicSpawns=(s.kit?.epicSpawns||(s.epicAppeared?[8]:[])).slice();draftMode=s.kit?.offerKind||'level';upgradeTiers={...(s.kit?.upgradeTiers||{})};leechBudget=0;build={...freshBuild(),...(s.kit?.build||{})};draft={...freshDraft(),...(s.kit?.draft||{}),banished:(s.kit?.draft?.banished||[]).slice()};shieldTime=s.kit?.shieldTime||0;pendingRarities=(s.kit?.pendingRarities||s.pending?.map(()=>0)||[]).slice();combatFX=[];stage=s.stage;runId=s.runId;runStats=P.blankStats();for(const k of Object.keys(runStats))runStats[k]=s.runStats[k]||0;totalTime=s.totalTime;stageDamage=s.stageDamage;t=s.t;kills=s.kills;level=s.level;xp=s.xp;need=s.need;damage=s.damage;interval=s.interval;if(s.version===1){const legacy=heroes[selected].gun?.23:heroes[selected].name==='LYRA'?.45:.58;interval=Math.max(.12,heroInterval(heroes[selected])*s.interval/legacy);if(heroes[selected].name==='BRANN')damage=Math.round(damage*48/35);}multi=s.multi;orbit=s.orbit;magnet=s.magnet;regen=s.regen;weaponRank=s.weaponRank;evolved=s.evolved;dashCD=s.dashCD;novaCD=s.novaCD;balance={...s.balance};bossAppeared=s.bossAppeared;bossDefeated=s.bossDefeated;epicAppeared=s.epicAppeared;seed=s.seed;chooseMap(s.map);p={};for(const k of ['x','z','hp','max','speed','r','angle','dx','dz','inv','walk'])p[k]=s.player[k];if(blocked(p.x,p.z,p.r)){const safe=safeSpawn();p.x=safe.x;p.z=safe.z}enemies=s.enemies.map(e=>({...e}));gems=s.gems.map(e=>({...e}));hostile=s.hostile.map(e=>({...e}));hazards=s.hazards.map(e=>({...e}));shots=[];fx=[];challenge=s.challenge?{...s.challenge}:null;challengeDone=new Set(s.done);upgradesTaken={};synergyCache=null;for(const u of upgrades){const count=s.upgrades[u.name];if(Number.isInteger(count)&&count>0&&count<10001)upgradesTaken[u.name]=count}pendingChoices=s.pending?s.pending.slice():null;spawnTimer=.3;shotTimer=.1;navTimer=0;autosaveClock=profileClock=0;keys={};camera.x=p.x;camera.z=p.z;$('#heroName').textContent=heroes[selected].name;$('#heroIcon').textContent=heroes[selected].icon;flowField(p);rebuildBuild();syncProfile();P.write(P.PROFILE_KEY,profile);if(s.phase==='round-clear')showRoundClear();else if(s.phase==='upgrade')showUpgrade(pendingChoices);else{mode='playing';pause()}hud();toast('Výprava načtena · kolo '+stage);return true}
function resumeGame(){RF.music?.start();const s=getSaved();if(!s){toast('Uloženou výpravu nelze načíst. Můžeš importovat zálohu.');return}try{restore(s)}catch(e){toast('Načtení selhalo: '+e.message)}}
function requestNewGame(){if(!getSaved()){start();return}modal('Začít novou výpravu?','Nová hra nahradí uloženou výpravu. Achievementy a celkové statistiky zůstanou.',start,'ANO, NOVÁ VÝPRAVA');$('#overlay .modal').insertAdjacentHTML('beforeend','<button id="cancelNew" class="secondary">ZPĚT</button>');$('#cancelNew').onclick=menu}
function setupMenuProgress(){const s=getSaved();$('#continueGame').hidden=!s;if(s)$('#continueGame').textContent='POKRAČOVAT · KOLO '+s.stage+' · '+heroes[s.hero].name;$('#continueGame').onclick=resumeGame;$('#saveSummary').textContent=s?RF.maps[s.map].name+' · '+difficulties[s.difficulty].name+' · '+fmt(s.t)+' / 05:00':'Zatím není uložená výprava.';$('#achievements').textContent='ACHIEVEMENTY '+Object.keys(profile.unlocked).length+' / '+P.achievements.length;$('#achievements').onclick=showAchievements;$('#menuExport').onclick=exportProgress;$('#menuImport').onclick=()=>$('#importFile').click();$('#storageHint').textContent=P.available()?'Automatické ukládání každých 10 s · zálohu můžeš exportovat.':'Místní ukládání není dostupné. Pro zachování postupu použij export.';$('#stageText').textContent='KOLO 1';$('#campaignInfo').textContent='Nekonečná výprava · kola po pěti minutách';}
function updateKitHUD(){const h=heroes[selected];$('#dash small').textContent=h.name==='BRANN'?'NÁRAZ':h.name==='LYRA'?'KROK':h.name==='KAEL'?'VÝPAD':'KOTOUL';$('#nova small').textContent=h.gun?'SALVA':h.name==='BRANN'?'ŠTÍT + ÚDER':h.name==='LYRA'?'METEOR':'KRUHOVÁ SEČ';$('#dash').title=kitText();$('#nova').title=kitText();}
function updateSynergyHUD(){$('#synergyHUD').textContent=activeSynergies().length?'SYNERGIE · '+activeSynergies().map(s=>s.name).join(' · '):'Synergie odemkneš kombinací vylepšení.'}
function updateProgressControls(){$('#save').disabled=!['playing','paused','upgrade','round-clear'].includes(mode)}
function showAchievements(){if(mode==='playing')pause();const previous=mode,panel=$('#overlay'),saved=Array.from(panel.children);mode='achievements';const achieved=Object.keys(profile.unlocked).length;panel.innerHTML='<div class="modal achievements"><div class="eyebrow">TRVALÝ PROFIL / '+achieved+' Z '+P.achievements.length+'</div><h2>Tvá kronika.</h2><p>Úspěchy zůstávají mezi výpravami. Nemění sílu nové postavy.</p><div class="achievement-grid">'+P.achievements.map(a=>{const done=!!profile.unlocked[a.id],n=a.mask?P.countBits(profile.stats[a.key]):profile.stats[a.key];return`<div class="achievement ${done?'unlocked':''}"><b>${done?'🏆':'◇'} ${a.name}</b><span>${a.desc}</span><small>${done?'ODEMČENO':Math.min(n,a.goal)+' / '+a.goal}</small></div>`}).join('')+'</div><button id="achievementBack" class="primary">ZPĚT</button></div>';panel.style.display='flex';$('#achievementBack').onclick=()=>{panel.replaceChildren(...saved);mode=previous};}
function exportProgress(){if(mode==='playing')pause();syncProfile();const s=snapshot()||getSaved();const bundle={format:'riftfall-backup',version:1,exportedAt:Date.now(),profile,save:s};const blob=new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='riftfall-zaloha-'+new Date().toLocaleDateString('sv-SE')+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Záloha obsahuje výpravu i achievementy.')}
async function importProgress(e){const input=e.target,file=input.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Soubor je příliš velký (max. 2 MB).');const bundle=JSON.parse(await file.text());if(bundle.format!=='riftfall-backup'||bundle.version!==1)throw Error('Nepodporovaný formát zálohy.');const imported=P.validateProfile(bundle.profile),s=bundle.save===null?null:P.validateSave(bundle.save);const merged=P.mergeProfiles(profile,imported);const stored=s?P.write(P.SAVE_KEY,s):true;profile=merged;const profileStored=P.write(P.PROFILE_KEY,profile);if(s&&!stored){restore(s);toast('Záloha načtena v paměti. Postup zachovej exportem.')}else{menu();toast(profileStored?'Záloha načtena. Achievementy byly sloučeny.':'Profil načten v paměti. Pro zachování použij export.')}}catch(err){toast('Import selhal: '+err.message)}finally{input.value=''}}

const menuHTML=$('#overlay').innerHTML;
function menu(){mode='menu';$('#epicStatus').textContent='';keys={};enemies=[];hostile=[];shots=[];gems=[];hazards=[];challenge=null;$('#bossHud').hidden=true;$('#timer').textContent='00:00';$('#kills').textContent='0 ELIMINACÍ';$('#challengeStatus').textContent='Výzvy u zlatých oltářů · aktivace F';$('#evolutionStatus').textContent='Vývoj zbraně 0 / 4';$('#interact').hidden=true;$('#overlay').innerHTML=menuHTML;$('#overlay').style.display='flex';$('#overlay').style.background='';$('#record').textContent='NEJVYŠŠÍ KOLO '+profile.stats.bestStage;$('#heroes').innerHTML=heroes.map((h,i)=>`<button class="hero ${i===selected?'selected':''}" data-hero="${i}"><span class="symbol">${h.icon}</span><b>${h.name}</b><small>${h.role}</small></button>`).join('');document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{selected=+b.dataset.hero;menu()});$('#maps').innerHTML=RF.maps.map((m,i)=>`<button data-map="${i}" class="map-card map-${m.id} ${i===mapIndex?'selected':''}"><div class="map-art"><i></i><i></i><i></i></div><b>${m.name}</b><small>${m.inspiration}</small></button>`).join('');document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{chooseMap(+b.dataset.map);menu()});$('#difficulty').innerHTML=difficulties.map((d,i)=>`<button data-difficulty="${i}" class="${difficulty===i?'selected':''}">${d.name}</button>`).join('');document.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=+b.dataset.difficulty;menu()});$('#difficultyInfo').textContent=difficulty?'Více nepřátel · +50 % HP · +35 % poškození · +18 % rychlosti':'Vyvážený začátek s pozvolna rostoucí obtížností';$('#mapDetail').textContent=activeMap.subtitle+' · '+(mapIndex===1?'Most 38 × 120 m':'120 × 120 m');$('#mapTitle').textContent=activeMap.name.toUpperCase();setupMenuProgress();$('#start').onclick=requestNewGame;$('#heroName').textContent=heroes[selected].name;$('#heroIcon').textContent=heroes[selected].icon;$('#heroKit').textContent=kitText();$('#hpText').textContent=heroes[selected].hp+' / '+heroes[selected].hp;$('#hpBar').style.width='100%';$('#xpBar').style.width='0%';$('#xpText').textContent='ÚROVEŇ 1'}
function start(){RF.music?.start();stage=1;totalTime=0;stageDamage=0;runId=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);runStats=P.blankStats();runStats.heroMask=1<<selected;runStats.bestStage=1;chooseMap(mapIndex);const h=heroes[selected];p={x:0,z:2.7,r:.4,hp:h.hp,max:h.hp,speed:h.speed,angle:0,dx:0,dz:-1,inv:0,walk:0};enemies=[];shots=[];gems=[];fx=[];hazards=[];hostile=[];epicAppeared=false;muzzle=0;weaponRank=0;evolved=false;rewardTokens=[];epicSpawns=[];draftMode='level';upgradeTiers={};build=freshBuild();leechBudget=0;draft=freshDraft();pendingRarities=[];shieldTime=0;combatFX=[];challenge=null;challengeDone=new Set();eliteClock=0;t=kills=xp=spawnTimer=shotTimer=navTimer=dashCD=novaCD=orbit=regen=0;level=1;need=8;damage=h.damage;interval=heroInterval(h);multi=1;magnet=2.3;bossAppeared=bossDefeated=false;upgradesTaken={};synergyCache=null;keys={};mode='playing';$('#overlay').style.display='none';$('#bossHud').hidden=true;$('#heroName').textContent=h.name;$('#heroIcon').textContent=h.icon;$('#pause').textContent='Ⅱ';$('#buildList').innerHTML='↗ &nbsp; Střepy trhliny';flowField(p);balance=computeBalance(1);syncProfile();autosaveClock=0;profileClock=0;pendingChoices=null;toast('Kolo 1 · přežij 5 minut a poraz strážce.');hud();saveGame(true)}
function pause(){if(mode==='playing'){mode='paused';keys={};modal('Čas se zastavil.','Trhlina počká. Až budeš připravený, vrať se do boje.',pause,'POKRAČOVAT');$('#overlay .modal').insertAdjacentHTML('beforeend','<button id="pauseMenu" class="secondary">HLAVNÍ MENU</button>');$('#pauseMenu').onclick=requestMenu;$('#overlay .modal').insertAdjacentHTML('beforeend','<button id="pauseSave" class="secondary">ULOŽIT VÝPRAVU</button><button id="pauseExport" class="secondary">EXPORTOVAT ZÁLOHU</button>');$('#pauseSave').onclick=()=>saveGame(false);$('#pauseExport').onclick=exportProgress;$('#pause').textContent='▷';saveGame(true)}else if(mode==='paused'){RF.music?.start();mode='playing';$('#overlay').style.display='none';$('#pause').textContent='Ⅱ'}}
$('#pause').onclick=pause;$('#musicToggle').onclick=()=>{const active=RF.music?.setEnabled(!RF.music.enabled);$('#musicToggle').textContent=active?'Hudba zapnutá':'Hudba vypnutá'};$('#musicVolume').oninput=e=>RF.music?.setVolume(+e.target.value/100);$('#musicVolume').value=(RF.music?.volume??.22)*100;$('#musicToggle').textContent=RF.music?.enabled?'Hudba zapnutá':'Hudba vypnutá';$('#exit').onclick=requestMenu;$('#brand').onclick=e=>{e.preventDefault();if(mode==='playing')pause()};$('#quality').onclick=()=>{quality=!quality;RF.setQuality(quality);$('#quality').textContent='Grafika: '+(quality?'vysoká':'úsporná')};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='Zvuk: '+(sound?'zapnutý':'vypnutý');beep(550)};
function particles(x,z,color,n=10){for(let i=0;i<n;i++)fx.push({x,y:.7,z,vx:range(-3,3),vy:range(1,5),vz:range(-3,3),life:range(.3,.7),color})}
$('#dash').onclick=useMobility;$('#nova').onclick=useAbility;$('#interact').onclick=activateChallenge;
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','f5'].includes(k))e.preventDefault();keys[k]=true;if(e.repeat)return;if(k==='escape')pause();if(k==='f5'){e.preventDefault();manualSave()}if(k===' ')useMobility();if(k==='e')useAbility();if(mode==='upgrade'){if(k==='r')rerollChoices();if(k==='b')toggleBanish();if(k==='x')skipChoice();}if(k==='f')activateChallenge();if(mode==='upgrade'&&['1','2','3'].includes(k)){const b=document.querySelector(`[data-up="${+k-1}"]`);if(b)b.click()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)RF.music?.suspend();else RF.music?.resume()});addEventListener('pagehide',()=>{saveGame(true);P.write(P.PROFILE_KEY,profile)});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};if(mode==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause()});$('#scene').addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom+e.deltaY*.015,17,34)},{passive:false});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false});
function spawnEnemy(boss=false,forced){let x,z,valid=false;for(let i=0;i<120;i++){const a=range(0,TWO),r=range(14,21);x=clamp(p.x+Math.sin(a)*r,-HALF+2,HALF-2);z=clamp(p.z+Math.cos(a)*r,-HALF+2,HALF-2);if(distance({x,z},p)>9&&!blocked(x,z,1.3)&&flow[cell(x,z)]>=0){valid=true;break}}if(!valid)return false;const pool=t<25?[0,0,0,4]:[0,0,0,4,4,5,1,1,2,6,7,7];const type=boss?3:forced!==undefined?forced:pool[Math.floor(rng()*pool.length)],d=defs[type];const hp=(d.hp+(boss?0:t*.3))*difficulties[difficulty].hp*(boss?balance.hp*1.1-.1:balance.hp);enemies.push({x,z,r:d.r,type,hp,max:hp,speed:d.speed*difficulties[difficulty].speed*balance.speed,angle:0,walk:range(0,10),cool:range(1.5,3.5),flash:0,variant:rng()<.5});const e=enemies[enemies.length-1];if(!isEpic(e)&&t>35&&rng()<Math.min(.3,difficulties[difficulty].elite+.015*(stage-1)))makeElite(e);return true}
function hitRaw(e,n){if(e.hp<=0)return;e.hp-=n;e.flash=.1;if(e.hp<=0){kills++;runStats.kills++;if(e.elite)runStats.elites++;syncProfile();particles(e.x,e.z,e.type===3?C.gold:e.type===2?C.pink:C.moss,12);dropXP(e.x,e.z,Math.max(1,Math.round((e.elite?9:e.type===3?45:e.type===8?15:e.type===2?4:1)*balance.xp)));if(e.elite||rng()<.045)gems.push({x:e.x+.4,z:e.z,value:0,heal:true});if(isEpic(e)){rewardTokens.push({x:e.x,z:e.z,type:e.type});toast(epicName(e)+' PADL · zlatý token odměny')}if(e.type===3){bossDefeated=true;toast('Epický strážce padl. Udrž arénu do 05:00.');beep(880)}}}
function takeDamage(n,attacker=null){if(p.inv>0||mode!=='playing')return;const armor=Math.min(.65,build.armor+(hasSynergy('fortress')?.08:0));const dealt=n*difficulties[difficulty].damage*balance.damage*(1-armor)*(shieldTime>0?.5:1);if(attacker&&build.thorns)impact(attacker,dealt*build.thorns,true);stageDamage+=Math.min(p.hp,dealt);p.hp=Math.max(0,p.hp-dealt);p.inv=.65;particles(p.x,p.z,[1,.4,.3],8);beep(90);if(p.hp<=0)finish(false)}
